import { describe, it, expect } from 'vitest';
import { JSDOM } from 'jsdom';
import axe from 'axe-core';
import { renderPageHtml } from '../src/page.js';

// Set up a fresh DOM from the generator before running axe.
function setupDocument() {
  const dom = new JSDOM(renderPageHtml(), { url: 'https://example.com/recipes/pancakes' });
  global.document = dom.window.document;
  global.window = dom.window;
  // axe-core expects these to exist in non-browser environments
  global.Node = dom.window.Node;
  global.NodeList = dom.window.NodeList;
  global.getComputedStyle = dom.window.getComputedStyle;
}

/**
 * Run axe against the current document.
 *
 * NOTE: jsdom has no layout engine, so it cannot compute colors/backgrounds.
 * axe's `color-contrast` rule therefore always fails/errors here — it is
 * disabled explicitly and must be covered by manual review or a real browser.
 */
async function runAxe() {
  const results = await window.axe.run(document, {
    rules: {
      'color-contrast': { enabled: false }, // not computable in jsdom
    },
  });
  return results;
}

describe('recipe page accessibility (axe-core)', () => {
  it('has zero violations', async () => {
    const dom = new JSDOM(renderPageHtml(), { url: 'https://example.com/recipes/pancakes' });

    // Inject axe-core into the page and evaluate it there.
    const script = dom.window.document.createElement('script');
    script.textContent = axe.source;
    dom.window.document.body.appendChild(script);
    const results = await dom.window.eval('axe.run(document, { rules: { "color-contrast": { enabled: false } } })');

    const ids = results.violations.map((v) => v.id);
    if (ids.length > 0) {
      const details = results.violations
        .map((v) => `${v.id} (${v.impact}): ${v.nodes.length} node(s)\n${v.help}`)
        .join('\n---\n');
      console.error(`AXE VIOLATIONS:\n${details}`);
    }
    expect(ids, `violations: ${ids.join(', ')}`).toEqual([]);
  });
});

