import { describe, it, expect, beforeEach } from 'vitest';
import axe from 'axe-core';
import { renderPageHtml } from '../src/page.js';

/**
 * Mount the generated HTML into the shared jsdom document.
 * We parse first so the <html lang="..."> attribute is mirrored too,
 * while still literally setting documentElement.innerHTML.
 */
beforeEach(() => {
  const parsed = new DOMParser().parseFromString(renderPageHtml(), 'text/html');
  document.documentElement.innerHTML = parsed.documentElement.innerHTML;
  for (const attr of parsed.documentElement.attributes) {
    document.documentElement.setAttribute(attr.name, attr.value);
  }
});

async function runAxe() {
  return axe.run(document, {
    rules: {
      // jsdom has no layout engine, so colors/backgrounds cannot be computed.
      // This rule always fails here; disable it (verify contrast in a real browser).
      'color-contrast': { enabled: false },
    },
  });
}

describe('recipe page accessibility (axe-core)', () => {
  it('reports zero violations', async () => {
    const results = await runAxe();

    if (results.violations.length > 0) {
      const details = results.violations
        .map((v) => `[${v.id}] impact=${v.impact} — ${v.help}\n${v.nodes.map((n) => '   ' + n.html).join('\n')}`)
        .join('\n');
      console.error(`\nAXE VIOLATIONS (${results.violations.length}):\n${details}\n`);
    }

    expect(
      results.violations.map((v) => v.id),
      'axe found accessibility violations'
    ).toEqual([]);
  });
});

